  const portalLink = response?.url || response?.link || response?.portal_link;
  if (!portalLink) {
    throw new Error("Portal link was not returned by Scalekit.");
  }

  await fs.writeFile(OUTPUT_PATH, portalLink, "utf8");
  console.log(`Portal link saved to ${OUTPUT_PATH}`);
}

main().catch((error) => {
  console.error(error.message || error);
  process.exit(1);
});
